mapper.select:
select a.asset_id, a.asset_no, a.asset_name, a.dept_id, a.user_id, a.status, a.stock from biz_asset a left join sys_dept d on a.dept_id = d.dept_id where a.status != '2'
AND a.asset_name like concat('%', #{assetName}, '%')
AND a.status = #{status}
${params.dataScope}

select asset_id, asset_no, asset_name, dept_id, user_id, status, stock
from biz_asset
where dept_id = #{deptId}
  and ( ${filterExpr} )
order by ${orderColumn}

mapper.update:
update biz_asset
stock = #{stock}, status = #{status}, user_id = #{userId},
where asset_id = #{assetId}
